import csv
import operator

def evaluate(expression, variables):
    """
    Safely evaluates a mathematical expression with given variables.
    """
    allowed_operators = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
    }

    tokens = expression.replace('(', ' ( ').replace(')', ' ) ').split()

    # Basic shunting-yard algorithm
    values = []
    ops = []

    def precedence(op):
        if op in ['+', '-']:
            return 1
        if op in ['*', '/']:
            return 2
        return 0

    def apply_op(op, b, a):
        return allowed_operators[op](a, b)

    for token in tokens:
        if token.replace('.', '', 1).isdigit():
            values.append(float(token))
        elif token in variables:
            values.append(variables[token])
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                op = ops.pop()
                val2 = values.pop()
                val1 = values.pop()
                values.append(apply_op(op, val2, val1))
            ops.pop()  # Pop the '('
        elif token in allowed_operators:
            while (ops and ops[-1] != '(' and
                   precedence(ops[-1]) >= precedence(token)):
                op = ops.pop()
                val2 = values.pop()
                val1 = values.pop()
                values.append(apply_op(op, val2, val1))
            ops.append(token)

    while ops:
        op = ops.pop()
        val2 = values.pop()
        val1 = values.pop()
        values.append(apply_op(op, val2, val1))

    return values[0]

def main():
    """
    Reads formulas from a CSV file, evaluates them, and prints the results.
    """
    with open('/workspace/tools/conversions.csv', 'r') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            formula = row['formula']
            if formula:
                variables = {
                    'mg_per_ml': 10,
                    'dilution': 2,
                    'sample_mass_g': 5,
                }
                try:
                    result = evaluate(formula, variables)
                    print(f"Formula: '{formula}' -> Result: {result}")
                except Exception as e:
                    print(f"Could not evaluate formula '{formula}': {e}")

if __name__ == "__main__":
    main()

