import requests, json, re, sys
base = 'http://the-agent-company.com:3000'
user = 'theagentcompany'
password = 'theagentcompany'
keywords = re.compile(r'ext-6414|f153b2|OPS-8071|approval|sign-?off|written approval|approved', re.I)
results = []
try:
    r = requests.post(base + '/api/v1/login', json={'user': user, 'password': password}, timeout=10)
    if r.status_code != 200:
        print('LOGIN_ERROR', r.status_code, r.text[:500])
        sys.exit(0)
    data = r.json().get('data', {})
    token = data.get('authToken')
    userId = data.get('userId')
    headers = {'X-Auth-Token': token, 'X-User-Id': userId}
    # channels
    rc = requests.get(base + '/api/v1/channels.list', headers=headers, timeout=10)
    if rc.status_code == 200:
        chs = rc.json().get('channels', [])
        for ch in chs:
            roomId = ch.get('_id')
            name = ch.get('name')
            try:
                rm = requests.get(base + '/api/v1/channels.messages', headers=headers, params={'roomId': roomId, 'count': 100}, timeout=10)
                if rm.status_code == 200:
                    msgs = rm.json().get('messages', [])
                    for m in msgs:
                        txt = m.get('msg','')
                        if txt and keywords.search(txt):
                            results.append({'channel': name, 'roomId': roomId, 'message': m})
            except Exception as e:
                print('CHANNEL_MSG_ERROR', name, e)
    else:
        print('CHANNELS_LIST_ERROR', rc.status_code, rc.text[:500])
    # groups
    rg = requests.get(base + '/api/v1/groups.list', headers=headers, timeout=10)
    if rg.status_code == 200:
        gps = rg.json().get('groups', [])
        for g in gps:
            roomId = g.get('_id')
            name = g.get('name')
            try:
                rm = requests.get(base + '/api/v1/groups.messages', headers=headers, params={'roomId': roomId, 'count': 100}, timeout=10)
                if rm.status_code == 200:
                    msgs = rm.json().get('messages', [])
                    for m in msgs:
                        txt = m.get('msg','')
                        if txt and keywords.search(txt):
                            results.append({'group': name, 'roomId': roomId, 'message': m})
            except Exception as e:
                print('GROUP_MSG_ERROR', name, e)
    else:
        print('GROUPS_LIST_ERROR', rg.status_code, rg.text[:500])
    # direct messages (im)
    rim = requests.get(base + '/api/v1/im.list', headers=headers, timeout=10)
    if rim.status_code == 200:
        ims = rim.json().get('ims', [])
        for im in ims:
            roomId = im.get('_id')
            user_name = im.get('u', {}).get('username')
            try:
                rm = requests.get(base + '/api/v1/im.messages', headers=headers, params={'roomId': roomId, 'count': 100}, timeout=10)
                if rm.status_code == 200:
                    msgs = rm.json().get('messages', [])
                    for m in msgs:
                        txt = m.get('msg','')
                        if txt and keywords.search(txt):
                            results.append({'dm_with': user_name, 'roomId': roomId, 'message': m})
            except Exception as e:
                print('IM_MSG_ERROR', user_name, e)
    # print summary
    print('FOUND', len(results), 'matches')
    for r in results:
        m = r['message']
        print('---')
        for k,v in r.items():
            if k != 'message':
                print(k.upper()+':', v)
        print('USER:', m.get('u'))
        print('TS:', m.get('ts'))
        print('MSG:', m.get('msg')[:500])
except Exception as e:
    print('ERROR', str(e))
